    sourceUrl: "https://www.xinhuanet.com/20260530/b3a1b0ae563a40078a2bfdb0fe917057/c.html",
    publishedAt: "2026-05-30T08:00:00.000Z",
    updatedAt: "2026-05-30T14:47:21.517Z",
    importance: "normal"
